// Claude's review tests for A12 (call sequences). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type MockResponse, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const step = (status: number, body: string): MockResponse => ({ status, headers: { 'content-type': 'text/plain' }, body, bodyEncoding: 'text', delayMs: 0 });

function mock(id: string, urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return { id, name: id, enabled: true, method: 'ANY', urlPattern, response: step(200, 'fixed'), source: 'manual', createdAt: 0, ...extra };
}

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'default',
    scenarios: [
      {
        id: 'default',
        name: 'Default',
        mocks: [
          mock('job', '/api/job', { reply: 'sequence', sequence: { steps: [step(202, 'pending'), step(202, 'pending'), step(200, 'done')], after: 'stay' } }),
          mock('flip', '/api/flip', { reply: 'sequence', sequence: { steps: [step(200, 'A'), step(200, 'B')], after: 'loop' } }),
          mock('count', '/api/count', { reply: 'code', code: 'return { n: req.callCount };' }),
          mock('plain', '/api/plain'),
        ],
      },
      { id: 'other', name: 'Other', mocks: [mock('x', '/api/x')] },
    ],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

const call = (page: Page, url: string, times = 1) =>
  page.evaluate(async ({ url, times }) => {
    const out: string[] = [];
    for (let i = 0; i < times; i++) {
      const r = await fetch(url);
      out.push(`${r.status} ${await r.text()}`);
    }
    return out;
  }, { url, times });

test('stay: pending, pending, done, done; a reload starts over', async () => {
  const { page, panel } = await open();
  try {
    expect(await call(page, '/api/job', 4)).toEqual(['202 pending', '202 pending', '200 done', '200 done']);
    await page.reload();
    expect(await call(page, '/api/job', 1)).toEqual(['202 pending']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('loop starts over; each mock counts on its own; fetch and XHR share the count', async () => {
  const { page, panel } = await open();
  try {
    expect(await call(page, '/api/flip', 1)).toEqual(['200 A']);
    expect(await call(page, '/api/job', 1)).toEqual(['202 pending']);
    const viaXhr = await page.evaluate(() => new Promise<string>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('GET', '/api/flip');
      x.onload = () => resolve(x.responseText);
      x.send();
    }));
    expect(viaXhr).toBe('B');
    expect(await call(page, '/api/flip', 1)).toEqual(['200 A']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a code mock sees req.callCount', async () => {
  const { page, panel } = await open();
  try {
    expect(await call(page, '/api/count', 3)).toEqual(['200 {"n":1}', '200 {"n":2}', '200 {"n":3}']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('switching the scenario away and back starts the count over', async () => {
  const { page, panel } = await open();
  try {
    expect(await call(page, '/api/job', 2)).toEqual(['202 pending', '202 pending']);
    await panel.getByTestId('scenario-chip').filter({ hasText: 'Other' }).first().click();
    await expect.poll(async () => (await readState()).projects[0]!.activeScenarioId).toBe('other');
    await call(page, '/api/x', 1);
    await panel.getByTestId('scenario-chip').filter({ hasText: 'Default' }).first().click();
    await expect.poll(async () => (await readState()).projects[0]!.activeScenarioId).toBe('default');
    await page.waitForTimeout(300);
    expect(await call(page, '/api/job', 1)).toEqual(['202 pending']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the editor edits steps; saving a change starts the count over', async () => {
  const { page, panel } = await open();
  try {
    expect(await call(page, '/api/job', 3)).toEqual(['202 pending', '202 pending', '200 done']);
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'job' }).click();
    await expect(panel.getByTestId('reply-sequence')).toHaveClass(/active/);
    await expect(panel.getByTestId('seq-step')).toHaveCount(3);
    await expect(panel.getByTestId('seq-after')).toHaveValue('stay');

    await panel.getByTestId('seq-step').nth(1).getByTestId('seq-step-remove').click();
    await panel.getByTestId('seq-step').nth(0).getByTestId('seq-body').fill('queued');
    await panel.getByTestId('seq-after').selectOption('loop');
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[0]!.sequence).toEqual({
      steps: [step(202, 'queued'), step(200, 'done')],
      after: 'loop',
    });
    await page.waitForTimeout(300);
    expect(await call(page, '/api/job', 3)).toEqual(['202 queued', '200 done', '202 queued']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('switching a fixed mock to Sequence starts with its fixed reply as step 1', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'plain' }).click();
    await panel.getByTestId('reply-sequence').click();
    await expect(panel.getByTestId('seq-step')).toHaveCount(1);
    await expect(panel.getByTestId('seq-step').nth(0).getByTestId('seq-status')).toHaveValue('200');
    await expect(panel.getByTestId('seq-step').nth(0).getByTestId('seq-body')).toHaveValue('fixed');
    await panel.getByTestId('seq-step-add').click();
    await panel.getByTestId('seq-step').nth(1).getByTestId('seq-status').fill('500');
    await panel.getByTestId('seq-step').nth(1).getByTestId('seq-body').fill('boom');
    await panel.getByTestId('seq-step').nth(1).getByTestId('seq-delay').fill('20');
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[3]!.reply).toBe('sequence');
    const saved = (await readState()).projects[0]!.scenarios[0]!.mocks[3]!;
    // Every step carries the mock's headers.
    expect(saved.sequence).toEqual({
      steps: [step(200, 'fixed'), { ...step(500, 'boom'), delayMs: 20 }],
      after: 'stay',
    });
    await page.reload();
    expect(await call(page, '/api/plain', 3)).toEqual(['200 fixed', '500 boom', '500 boom']);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Test bar shows step 1 and does not move the page count', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('test-method').selectOption('GET');
    await panel.getByTestId('test-url').fill('/api/job');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-status')).toContainText('202');
    await expect(panel.getByTestId('test-body-out')).toContainText('pending');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-status')).toContainText('202');
    expect(await call(page, '/api/job', 1)).toEqual(['202 pending']);
  } finally {
    await panel.close();
    await page.close();
  }
});
